for _round in range(self.cfg.max_tool_rounds):
    final = await self._stream_turn(model, effort, emit)
    self.messages.append({"role": "assistant", "content": final.content})

    if final.stop_reason == "refusal":
        await emit(" Sorry, I can't help with that one.")
        return "".join(reply_parts)

    tool_uses = [b for b in final.content if b.type == "tool_use"]
    if not tool_uses:
        return "".join(reply_parts)
    if final.stop_reason == "max_tokens":
        # A truncated tool input can parse as a valid partial object; don't run it.
        raise ClaudeUnavailable("My answer got cut off. Try asking a shorter question.")

    results = []
    for block in tool_uses:
        content, is_error = await run_tool(block.name, block.input, self.tools_ctx)
        results.append({"type": "tool_result", "tool_use_id": block.id, "content": content, "is_error": is_error})
    # All results for one assistant turn go back in a single user message.
    self.messages.append({"role": "user", "content": results})

raise ClaudeUnavailable("I got stuck going back and forth with my tools. Try asking again.")

_SENTENCE_END = re.compile(r"(?<=[.!?])\s+|\n+")

def feed(self, text: str) -> list[str]:
    self._buf += text
    out = []
    while True:
        m = None
        for cand in _SENTENCE_END.finditer(self._buf):
            if cand.start() >= self._min:
                m = cand
                break
        if m is None:
            return out
        sentence, self._buf = self._buf[: m.start()].strip(), self._buf[m.end():]
        if sentence:
            out.append(sentence)

void loop() {
  wdt_reset();

  readSerial();

  // Read the clock after handling commands: a D command stamps lastDriveMs
  // with millis(), and a 'now' taken earlier would make now - lastDriveMs
  // underflow and trip the watchdog falsely.
  unsigned long now = millis();

  if (!watchdogTripped && now - lastDriveMs > WATCHDOG_MS) {
    stopNow();
    watchdogTripped = true;
    Serial.println(F("WDT"));
  }
